<script lang="ts">
 import {onMount} from 'svelte'
 import {getSyncState} from './api'
 import PageHeader from './PageHeader.svelte'
 import TerminalCardActions from './terminal/TerminalCardActions.svelte'
 import ActiveSessions from './terminal/ActiveSessions.svelte'
 import CommandLibrary from './terminal/CommandLibrary.svelte'
 import WorkspaceDialog from './terminal/WorkspaceDialog.svelte'
 import TerminalCommandReference from './terminal/TerminalCommandReference.svelte'
 import {terminalMachines,machineHealth,readiness,TerminalError,type TerminalMachine,type MachineHealth} from './terminal/api'
 import {machineLink} from './machineSetup'
 let {canWrite,terminalAccess,monitorAccess}:{canWrite:boolean;terminalAccess:boolean;monitorAccess:boolean}=$props()
 let machines=$state<TerminalMachine[]>([]),health=$state<MachineHealth[]>([]),loading=$state(true),busy=$state(false),error=$state(''),checked=$state(0),now=$state(Date.now()),commandsOpen=$state(false),helpOpen=$state(false)
 let alive=true;const abort=new AbortController()
 const stale=$derived(!!error||checked>0&&now-checked>45000)
 const ready=$derived(machines.filter(item=>item.ready).length)
 function memory(item:MachineHealth|undefined){const total=item?.connection?.report?.memory.totalBytes.value,available=item?.connection?.report?.memory.availableBytes.value;return total&&available!=null?`${Math.round((1-available/total)*100)}% memory`:'Memory unavailable'}
 async function refresh(){
  if(busy||!alive)return;busy=true
  try{
   if(terminalAccess){const[next,metrics]=await Promise.all([terminalMachines(AbortSignal.any([abort.signal,AbortSignal.timeout(10000)])),machineHealth(AbortSignal.any([abort.signal,AbortSignal.timeout(10000)])).catch(()=>null)]);if(!alive)return;machines=next;health=metrics?.machines||[]}
   else if(monitorAccess){const state=await getSyncState();if(!alive)return;machines=(state.agents||[]).map(item=>({agentId:item.id,host:item.host,ready:!item.paused&&item.lastSeen>Date.now()-90000}))}
   checked=Date.now();error=''
  }catch(e){if(alive&&!abort.signal.aborted){if(e instanceof TerminalError&&[401,403].includes(e.status)){machines=[];health=[];checked=0}error=e instanceof Error?e.message:'Connection status is unavailable.'}}
  finally{if(alive){loading=false;busy=false}}
 }
 onMount(()=>{void refresh();const wake=()=>{now=Date.now();if(document.visibilityState==='visible')void refresh()};const timer=setInterval(wake,15000);document.addEventListener('visibilitychange',wake);return()=>{alive=false;abort.abort();clearInterval(timer);document.removeEventListener('visibilitychange',wake)}})
</script>
<PageHeader eyebrow="Ey up. Your AI control room" title="Your fleet. Ready for work." lede="Reach your machines, use installed AI agents, and keep your toolkit and ongoing work in good order.">
 {#snippet actions()}{#if terminalAccess}<a class="btn" href="/terminals">Open terminals →</a>{/if}{#if canWrite}<a class="btn primary" href="/machines#connect-machine">Connect a machine</a>{/if}{/snippet}
</PageHeader>
{#if terminalAccess}<ActiveSessions/>{/if}
<section class="machines-section" aria-labelledby="connected-machines-title" aria-busy={loading}>
 <header class="section-heading"><div><p class="eyebrow">One place to connect</p><h2 id="connected-machines-title">Your machines <span class="count">{machines.length}</span></h2><p>{loading?'Checking connections…':stale?'Showing the last received connection status.':terminalAccess?`${ready} ready for terminals`:'Machine connection overview'}</p></div><button class="btn quiet" aria-label="Refresh machine connections" disabled={busy} onclick={()=>void refresh()}>↻ Refresh</button></header>
 {#if error}<p class="connection-error" role="alert">{error} <button onclick={()=>void refresh()}>Try again</button></p>{/if}
 {#if !terminalAccess}<p class="access-note">{canWrite?'Browser terminals require account-based sign-in on this instance.':'Your account can view machines. Terminal access requires a write role.'}</p>{/if}
 {#if loading}<div class="machine-grid" aria-hidden="true">{#each [0,1,2] as n (n)}<div class="machine-skeleton"><i></i><i></i><i></i></div>{/each}</div>
 {:else if machines.length}<div class="machine-grid">{#each machines as item (item.agentId)}
  {@const metrics=health.find(row=>row.agentId===item.agentId)}
  <TerminalCardActions machine={item} disabled={!terminalAccess||stale}>{#snippet children(open,controls)}
  <article oncontextmenu={event=>{if(terminalAccess)open(event)}} class="machine-card" aria-label={`Machine ${item.host}`}><a class="card-link" href={machineLink(item.host)} aria-label={`View ${item.host} machine details`}></a><header><span class="machine-mark" aria-hidden="true">›_</span><span class="machine-status" class:ready={item.ready&&!stale}><i></i>{stale?'Last known':item.ready?(terminalAccess?'Ready':'Connected'):item.capabilities?.terminalEnabled?'Connecting':'Setup needed'}</span></header>
   <div class="machine-name-row"><h3>{item.host}</h3>{#if terminalAccess}{@render controls()}{/if}</div><p class="machine-context">{item.capabilities?.osUser?`${item.capabilities.osUser}@${item.host}`:terminalAccess?'Private machine connection':'Machine inventory available'}{#if item.capabilities?.os}<span>{item.capabilities.os}</span>{/if}</p>
   {#if terminalAccess&&metrics?.connection?.report}<div class="telemetry" class:old={!metrics.connection.reportFresh}><span>{metrics.connection.report.cpuPercent.value==null?'CPU unavailable':`${metrics.connection.report.cpuPercent.value.toFixed(0)}% CPU`}</span><span>{memory(metrics)}</span>{#if !metrics.connection.reportFresh}<span>Last known</span>{/if}</div>{:else}<p class="machine-note">{item.ready?'Your machine is available when you need it.':terminalAccess?readiness(item):'Open Machines for connection details.'}</p>{/if}
   <footer>{#if terminalAccess}<a class="btn" class:open={item.ready} href={`/terminals?agent=${encodeURIComponent(item.agentId)}`} aria-label={`${item.ready?'Open terminal':'View terminal setup'} on ${item.host}`}>{item.ready?'Open terminal':'View setup'} <span aria-hidden="true">→</span></a>{:else}<a class="btn" href="/machines">View machine →</a>{/if}{#if metrics?.connection?.rttMillis!=null&&metrics.connection.connected}<span class="rtt">{Math.round(metrics.connection.rttMillis)} ms</span>{/if}</footer>
  </article>{/snippet}</TerminalCardActions>
 {/each}</div>
 {:else if !error}<div class="first-machine"><span class="first-mark" aria-hidden="true">›_</span><h3>Your first machine belongs here.</h3><p>Connect a laptop or server, allow terminal access locally, then open its shell from your browser.</p>{#if canWrite}<a class="btn primary" href="/machines#connect-machine">Connect your first machine</a>{/if}<button class="btn quiet" onclick={()=>helpOpen=true}>Terminal setup guide</button></div>{/if}
</section>
{#if terminalAccess}<section class="workspace-shortcuts" aria-label="Workspace shortcuts"><a href="/profiles"><span class="shortcut-symbol" aria-hidden="true">▤</span><span><strong>Setups</strong><small>Give another machine a known starting point.</small></span><b aria-hidden="true">→</b></a><a href="/sync"><span class="shortcut-symbol" aria-hidden="true">↔</span><span><strong>Sync</strong><small>Choose destinations, preview and review changes.</small></span><b aria-hidden="true">→</b></a><button onclick={()=>commandsOpen=true}><span class="shortcut-symbol" aria-hidden="true">⌘</span><span><strong>Your command library</strong><small>Save once. Reach for it on any machine.</small></span><b aria-hidden="true">→</b></button><button onclick={()=>helpOpen=true}><span class="shortcut-symbol" aria-hidden="true">?</span><span><strong>Connection help</strong><small>Terminal consent, services and reconnecting.</small></span><b aria-hidden="true">→</b></button></section>{/if}
{#if commandsOpen}<CommandLibrary onclose={()=>commandsOpen=false}/>{/if}
{#if helpOpen}<WorkspaceDialog title="Terminal connection setup" onclose={()=>helpOpen=false}><p class="help-copy">Allow terminal access on each machine, then open it from your workspace. A browser disconnect leaves its shells running.</p><TerminalCommandReference/><p class="help-copy">On the machine, install tmux 3.2 or newer, then run:</p><pre>reet agent terminal setup</pre><a class="btn" href="/machines#connect-machine">Connect or finish setting up a machine →</a></WorkspaceDialog>{/if}
<style>
 .machine-name-row{display:flex;align-items:center;gap:8px;margin:17px 0 6px}.machine-name-row h3{flex:1;min-width:0;margin:0!important}.machine-name-row :global(.card-actions){flex:none;pointer-events:auto}
 .machines-section{margin:24px 0}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.eyebrow{font-size:.62rem;letter-spacing:.1em;text-transform:uppercase;color:var(--accent);margin:0 0 7px}h2{font:500 1.7rem var(--serif);margin:0;display:flex;align-items:center;gap:10px}.count{font:500 .72rem var(--sans);padding:3px 8px;border:1px solid var(--line);border-radius:20px;color:var(--muted)}.section-heading p:not(.eyebrow){font-size:.74rem;color:var(--muted);margin:6px 0 0}.section-heading .btn{font-size:.75rem;padding:7px 10px}.machine-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(290px,100%),1fr));gap:14px}.machine-card{position:relative;padding:20px;border:1px solid var(--line);border-radius:12px;background:var(--card);min-width:0;display:flex;flex-direction:column}.card-link{position:absolute;inset:0;border-radius:inherit;z-index:1}.card-link:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.machine-card>header,.machine-card>.machine-name-row,.machine-card>.machine-context,.machine-card>.machine-note,.machine-card>.telemetry{position:relative;z-index:2;pointer-events:none}.machine-card footer{position:relative;z-index:3}.machine-card>header{display:flex;align-items:center;justify-content:space-between;gap:8px}.machine-mark{font:500 1.5rem var(--mono);color:var(--accent);background:var(--tint);border:1px solid color-mix(in srgb,var(--accent) 20%,var(--line));width:40px;height:40px;border-radius:10px;display:grid;place-content:center}.machine-status{display:flex;align-items:center;gap:6px;font-size:.68rem;color:var(--muted)}.machine-status i{height:6px;width:6px;border-radius:50%;background:var(--muted)}.machine-status.ready{color:var(--good)}.machine-status.ready i{background:var(--good)}.machine-card h3{font:500 1.35rem var(--serif);margin:17px 0 6px;overflow-wrap:anywhere}.machine-context{font:.7rem var(--mono);color:var(--muted);margin:0;display:flex;flex-wrap:wrap;gap:8px;overflow-wrap:anywhere}.machine-context>span{font:.62rem var(--sans);border:1px solid var(--line);padding:1px 5px;border-radius:3px;text-transform:uppercase}.machine-note{font-size:.74rem;line-height:1.6;color:var(--muted);margin:16px 0;flex:1}.telemetry{display:flex;gap:14px;font:.69rem var(--mono);color:var(--muted);padding:16px 0;flex-wrap:wrap;flex:1}.telemetry.old{opacity:.75}.machine-card footer{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--line);padding-top:14px;margin-top:auto}.machine-card .btn{font-size:.74rem;min-height:34px;padding:7px 10px;justify-content:space-between;gap:16px}.machine-card .btn.open{background:var(--ink);border-color:var(--ink);color:var(--card)}.rtt{font:.65rem var(--mono);color:var(--muted)}.connection-error,.access-note{padding:12px;border-radius:8px;background:var(--tint);font-size:.78rem;line-height:1.6}.connection-error{color:var(--bad)}.connection-error button{border:0;background:transparent;text-decoration:underline;color:inherit;cursor:pointer}.first-machine{border:1px dashed var(--line);border-radius:12px;text-align:center;padding:36px 20px;background:var(--card)}.first-mark{font:2.5rem var(--mono);color:var(--accent)}.first-machine h3{font:500 1.7rem var(--serif);margin:14px 0 10px}.first-machine p{font-size:.85rem;line-height:1.7;color:var(--muted);max-width:58ch;margin:0 auto 20px}.first-machine .btn{margin:4px}.machine-skeleton{border:1px solid var(--line);border-radius:12px;padding:24px;background:var(--card);display:grid;gap:20px;height:220px}.machine-skeleton i{display:block;height:14px;background:var(--line);border-radius:5px}.machine-skeleton i:first-child{width:40px;height:40px}.machine-skeleton i:last-child{width:70%}.workspace-shortcuts{display:grid;grid-template-columns:1fr 1fr;gap:14px;border-top:1px solid var(--line);padding-top:22px;margin:28px 0}.workspace-shortcuts button,.workspace-shortcuts>a{display:flex;align-items:center;gap:12px;padding:16px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--ink);text-align:left;cursor:pointer;text-decoration:none}.shortcut-symbol{font:1.5rem var(--mono);color:var(--accent);min-width:32px;text-align:center}.workspace-shortcuts strong{display:block;font-size:.82rem}.workspace-shortcuts small{display:block;font-size:.72rem;color:var(--muted);margin-top:5px}.workspace-shortcuts b{margin-left:auto;color:var(--muted);font-weight:400}.help-copy{font-size:.82rem;line-height:1.7;color:var(--muted);margin:0}pre{padding:12px;border:1px solid var(--line);border-radius:6px;background:var(--bg);font:.78rem/1.7 var(--mono);overflow:auto}@media(max-width:650px){.machine-card{padding:17px}.workspace-shortcuts{grid-template-columns:1fr}.section-heading{gap:8px}h2{font-size:1.5rem}}
</style>
